/** The corner and press hooks. */
export const SHAPE_HOOKS = ["--basalt-button-radius", "--basalt-button-radius-lg", "--basalt-field-radius", "--basalt-field-radius-lg", "--basalt-button-press-scale"];
/** The private duration of a field's edge transition: set in a palette that sets a field's hover or active edge, `initial` in every other block. */
